// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/categories", wrapper.GetCategories)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/chat", wrapper.PostChat)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/chat/stream", wrapper.PostChatStream)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/classifications/queue", wrapper.GetClassificationQueue)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/classifications/{transaction_id}/correct", wrapper.PostClassificationCorrect)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/health", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/imports", wrapper.GetImports)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/imports", wrapper.PostImports)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/imports/preview", wrapper.PostImportsPreview)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/imports/{id}", wrapper.GetImport)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/imports/{id}/rollback", wrapper.PostImportRollback)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/llm/models", wrapper.GetLLMModels)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/transactions", wrapper.GetTransactions)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/transfers/candidates", wrapper.GetTransferCandidates)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/transfers/{id}/confirm", wrapper.PostTransferConfirm)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/transfers/{id}/reject", wrapper.PostTransferReject)
	})

	return r
}
